 const thread={id:THREAD,title:'御所に届ける願い',status:'open',messageCount:1,createdAt:'2026-11-22T10:00:00Z',updatedAt:'2026-11-22T10:00:00Z',requester:{id:'visitor-one',name:'参内した領主'},canReply:true};
 const data={chat:[message(1)],threads:[thread],messages:[message(1)],roster:[{id:'staff-one',name:'朝廷の担当者',title:'参議',officeJurisdiction:'kyoto',merit:2,completedUpgrades:2,isLeader:false,termId:'term-one',canBecomeEmperor:true}]},calls=[],frames=[];
